  +availableStorageSpace : float
}

class PickupRoute {
  +day : date
}

class VolunteerDriver {
  +availableDays : string[]
}

class SecondHandArticle {
  +description : string
  +dimensions : string
  +weight : float
  +rfidTag : string
}

class Category {
  +name : string
}

class Client {
  +homeAddress : string
  +neededCategories : string[]
}

