}

Resident "1" -- "*" ScheduledPickup : schedules
ScheduledPickup "*" -- "1" Resident : at address
ScheduledPickup "*" -- "1" Vehicle : assigned to
PickupRoute "1" -- "1" Vehicle : for
PickupRoute "1" -- "1..*" ScheduledPickup : includes
VolunteerDriver "1" -- "0..1" PickupRoute : drives
VolunteerDriver "1" -- "0..*" ScheduledPickup : performs pickup
VolunteerDriver "1" -- "0..*" SecondHandArticle : delivers
VolunteerDriver "1" -- "0..*" ScheduledPickup : performs delivery
SecondHandArticle "*" -- "1" Category : belongs to
SecondHandArticle "1" -- "1" Resident : provided by
SecondHandArticle "*" -- "1" H2SLocation : dropped off at
FoodItem "*" -- "1" H2SLocation : dropped off at
FoodItem "*" -- "1" FoodBank : delivered to
Client "1" -- "1" H2SLocation : receives from
Client "1" -- "1" Resident : is a type of
H2SLocation "1" -- "*" H2SEmployee : employs
H2SLocation "1" -- "*" Vehicle : operates
H2SLocation "1" -- "*" PickupRoute : manages
@enduml

